import React, { useRef, useState } from "react";
import "./zambrug.css";

const ZamZoom = () => {
  const imgRef = useRef(null);
  const lensRef = useRef(null);
  const resultRef = useRef(null);

  const [showLens, setShowLens] = useState(false);

  const handleMove = (e) => {
    const img = imgRef.current;
    const lens = lensRef.current;
    const result = resultRef.current;

    let rect = img.getBoundingClientRect();

    // Kursorning rasmga nisbiy koordinatasi
    let x = e.clientX - rect.left;
    let y = e.clientY - rect.top;

    let lensW = lens.offsetWidth / 2;
    let lensH = lens.offsetHeight / 2;

    // **Chegaralanish 100% ishlaydi**
    if (x < lensW) x = lensW;
    if (x > rect.width - lensW) x = rect.width - lensW;

    if (y < lensH) y = lensH;
    if (y > rect.height - lensH) y = rect.height - lensH;

    // LENS joylashuvi
    lens.style.left = x - lensW + "px";
    lens.style.top = y - lensH + "px";

    // ZOOM koeffitsientlari
    let cx = result.offsetWidth / lens.offsetWidth;
    let cy = result.offsetHeight / lens.offsetHeight;

    // BACKGROUND sozlash
    result.style.backgroundImage = `url(${img.src})`;
    result.style.backgroundSize =
      img.naturalWidth * cx + "px " + img.naturalHeight * cy + "px";

    result.style.backgroundPosition =
      `-${(x * cx) - result.offsetWidth / 2}px -${(y * cy) - result.offsetHeight / 2}px`;
  };

  return (
    <div className="zoom-wrapper">
      <div
        className="img-zoom-container"
        onMouseMove={handleMove}
        onMouseEnter={() => setShowLens(true)}
        onMouseLeave={() => setShowLens(false)}
      >
        <img
          ref={imgRef}
          src="/images/salom.jpg"
          className="zoom-image"
          alt=""
        />

        {showLens && <div ref={lensRef} className="img-zoom-lens"></div>}
      </div>

      <div ref={resultRef} className="img-zoom-result"></div>
    </div>
  );
};

export default ZamZoom;
